<?php
require_once __DIR__ . '/../../admin/implements/conexion.php';
require_once __DIR__ . '/funciones.php';
if (!empty($_SESSION['usuario']['id_usuario'])) { header('Location: ' . (($_SESSION['usuario']['rol'] ?? '') === 'Admin' ? '/app_biblioteca/admin/dashboard.php' : '/app_biblioteca/admin/usuarios/mi-cuenta.php')); exit; }
$errores=[];
if($_SERVER['REQUEST_METHOD']==='POST'){validarCsrf();$correo=strtolower(trim($_POST['correo']??''));$clave=$_POST['clave']??'';$documento=trim($_POST['documento']??'');$nombre=trim($_POST['nombre']??'');$lock=(int)$pdo->query("SELECT GET_LOCK('app_biblioteca_primer_admin',5)")->fetchColumn();$cuenta=(int)$pdo->query("SELECT COUNT(*) FROM usuarios WHERE rol='Admin'")->fetchColumn();if($lock===1&&$cuenta===0){header('Location: /app_biblioteca/admin/usuarios/registrarse.php');exit;}if(!filter_var($correo,FILTER_VALIDATE_EMAIL))$errores[]='Ingresa un correo válido.';else{$consulta=$pdo->prepare('SELECT id_usuario,nombre,documento,correo,password_hash,rol FROM usuarios WHERE correo=?');$consulta->execute([$correo]);$usuario=$consulta->fetch();if($usuario&&!empty($usuario['password_hash'])&&password_verify($clave,$usuario['password_hash'])){session_regenerate_id(true);$_SESSION['usuario']=['id_usuario'=>(int)$usuario['id_usuario'],'nombre'=>$usuario['nombre'],'correo'=>$usuario['correo'],'rol'=>$usuario['rol']];$_SESSION['token_csrf']=bin2hex(random_bytes(32));header('Location: '.($usuario['rol']==='Admin'?'/app_biblioteca/admin/dashboard.php':'/app_biblioteca/admin/usuarios/mi-cuenta.php'));exit;}$errores[]='Correo o contraseña incorrectos.';}}
iniciarPagina('Iniciar sesión');
?>
<section class="auth-card"><div class="auth-icon"><i class="bi bi-book-half"></i></div><h1>Biblioteca</h1><p>Inicia sesión para continuar.</p><?php foreach($errores as $error): ?><div class="alert alert-danger"><?= escapar($error); ?></div><?php endforeach; ?><form method="post"><input type="hidden" name="token_csrf" value="<?= escapar(tokenCsrf()); ?>"><div class="mb-3"><label class="form-label">Correo</label><input class="form-control" type="email" name="correo" required autocomplete="username" value="<?= escapar($_POST['correo']??''); ?>"></div><div class="mb-4"><label class="form-label">Contraseña</label><input class="form-control" type="password" name="clave" required autocomplete="current-password"></div><button class="btn btn-primary w-100">Iniciar sesión</button></form><p class="mt-3 mb-0 text-center">¿No tienes cuenta? <a href="/app_biblioteca/admin/usuarios/registrarse.php">Regístrate</a></p></section><?php finPagina(); ?>
